//! Checks the boundary refinement against QuPath's own output.
//!
//! Fixture generated by `parity/java/RefineBoundary.java` via
//! `./parity/record.sh`, recorded through the block detection runs between the
//! shape split and the area filter:
//!
//! ```java
//! FloatProcessor fpBoundaryCleanup = (FloatProcessor)fpDetection.duplicate();
//! fpBoundaryCleanup.blurGaussian(1);
//! fpBoundaryCleanup.convolve(new float[]{0, -1, 0, -1, 4, -1, 0, -1, 0}, 3, 3);
//! ByteProcessor bp2 = SimpleThresholding.thresholdAbove(fpBoundaryCleanup, 0.0);
//! bp2.copyBits(bp, 0, 0, Blitter.MIN);
//! bp.filter(ByteProcessor.MIN);
//! bp.copyBits(bp2, 0, 0, Blitter.MAX);
//! ```
//!
//! Needs no slide.
//!
//! Two checkpoints are asserted rather than one. `cleanup` — the sigma-1
//! Laplacian of Gaussian, compared **by its bits** — localises a failure to the
//! filters rather than to the masking, and it is where a difference would show
//! first: the interior of a flat image convolves to exactly zero, but the ring
//! one pixel inside the border lands at ±2.98e-08, and which of those the strict
//! `> 0.0` accepts is what `all-foreground`'s `bp2` records. `refined` is the
//! mask the whole block leaves, which is what the area filter is handed.
//!
//! The object count either side of the block is asserted too. A mask can agree
//! on every pixel and still trace to a different number of objects if one pixel
//! of a boundary moves, and on the recorded cases the block both splits objects
//! apart (`random-dense`, 7 to 117) and deletes them outright
//! (`lone-pixel-erased`, 1 to 0).

use qupath_pipeline::{BoundaryRefiner, FOREGROUND};
use qupath_watershed::RegionTracer;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/RefineBoundary.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn floats(text: &str) -> Vec<f32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn ints(text: &str) -> Vec<u32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("integer"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Widens a recorded 0/255 mask, checking it really is one.
fn mask(recorded: &[u32], name: &str, what: &str) -> Vec<u8> {
    recorded
        .iter()
        .map(|&v| {
            assert!(
                v == 0 || v == u32::from(FOREGROUND),
                "{name}: the recorded {what} holds {v}, which is neither 0 nor 255"
            );
            u8::try_from(v).expect("0 or 255")
        })
        .collect()
}

#[test]
fn matches_qupath_refine_boundary() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"cases\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut removed_total = 0usize;
    let mut at = 0usize;
    // One refiner and one tracer across every case: buffers left dirty by a
    // previous case would show up here and nowhere else.
    let mut refiner = BoundaryRefiner::new();
    let mut tracer = RegionTracer::new();
    let mut smoothed = Vec::new();
    let mut cleanup = Vec::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (expected_before, next) = scalar(cases, "objectsBefore", next);
        let (expected_after, next) = scalar(cases, "objectsAfter", next);
        let (detection_text, next) = between(cases, "\"detection\": [", "]", next);
        let (binary_text, next) = between(cases, "\"binary\": [", "]", next);
        let (cleanup_text, next) = between(cases, "\"cleanup\": [", "]", next);
        let (bp2_text, next) = between(cases, "\"bp2\": [", "]", next);
        let (refined_text, next) = between(cases, "\"refined\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let detection = floats(detection_text);
        let mut binary = mask(&ints(binary_text), name, "binary");
        let their_cleanup = floats(cleanup_text);
        let their_bp2 = mask(&ints(bp2_text), name, "bp2");
        let their_refined = mask(&ints(refined_text), name, "refined");

        assert_eq!(detection.len(), width * height, "{name}: detection image");
        assert_eq!(binary.len(), width * height, "{name}: input binary");
        assert_eq!(their_cleanup.len(), width * height, "{name}: cleanup");
        assert_eq!(their_bp2.len(), width * height, "{name}: bp2");
        assert_eq!(their_refined.len(), width * height, "{name}: refined");

        // What the block traced to before it ran, so the recorded input is
        // checked against the recorded count rather than taken on trust.
        let mut regions = vec![0u32; binary.len()];
        let before = tracer.trace_mask_into(&binary, &mut regions, width);
        assert_eq!(
            u64::from(before),
            index(expected_before) as u64,
            "{name}: objects before the refinement"
        );

        refiner.refine(&detection, &mut binary, width, &mut smoothed, &mut cleanup);

        // The sigma-1 Laplacian of Gaussian, bit for bit. Nothing here is
        // transcendental past the kernel, and `GaussianBlur.json` already pins
        // that, so any difference is a defect rather than a licensed ulp.
        for (at, (&theirs, &ours)) in their_cleanup.iter().zip(&cleanup).enumerate() {
            assert_eq!(
                ours.to_bits(),
                theirs.to_bits(),
                "{name}: pixel ({}, {}) cleans up to {ours}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        // `bp2` is never materialised by the port — the two lines are fused —
        // so it is reconstructed here from what it is defined to be. This is
        // what checks the strict `> 0.0` and the `MIN` against `bp` separately
        // from the erosion they are combined with.
        let ours_bp2: Vec<u8> = cleanup
            .iter()
            .zip(&mask(&ints(binary_text), name, "binary"))
            .map(|(&value, &was)| {
                if value > 0.0 && was != 0 {
                    FOREGROUND
                } else {
                    0
                }
            })
            .collect();
        for (at, (&theirs, &ours)) in their_bp2.iter().zip(&ours_bp2).enumerate() {
            assert_eq!(
                ours,
                theirs,
                "{name}: pixel ({}, {}) masks to {ours}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        for (at, (&theirs, &ours)) in their_refined.iter().zip(&binary).enumerate() {
            assert_eq!(
                ours,
                theirs,
                "{name}: pixel ({}, {}) refines to {ours}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        let after = tracer.trace_mask_into(&binary, &mut regions, width);
        assert_eq!(
            u64::from(after),
            index(expected_after) as u64,
            "{name}: objects after the refinement"
        );

        removed_total +=
            their_binary_set(&ints(binary_text)) - their_binary_set(&ints(refined_text));
        count += 1;
    }

    assert_eq!(count, 14, "expected 14 recorded cases");
    assert!(
        removed_total > 0,
        "the refinement should erode something across the fixture as a whole"
    );
}

fn their_binary_set(recorded: &[u32]) -> usize {
    recorded.iter().filter(|&&v| v != 0).count()
}

/// The cases that exist because a mutation of the port passes without them.
///
/// Listed by name so that a re-recording which quietly drops one is a failure
/// here rather than a silent loss of coverage — §5's "a convention nothing
/// exercises is not pinned".
#[test]
fn the_fixture_still_carries_the_cases_that_pin_the_conventions() {
    let text = std::fs::read_to_string(fixture()).expect("fixture; run ./parity/record.sh");
    for (name, why) in [
        (
            "all-foreground",
            "the erosion's border is replicated, so a full image erodes to nothing",
        ),
        (
            "positive-outside-bp",
            "bp2 is masked by bp, so the refinement cannot grow an object",
        ),
        (
            "lone-pixel-kept",
            "the final MAX restores what the erosion removed",
        ),
        (
            "lone-pixel-erased",
            "and it restores it only where the finer Laplacian agrees",
        ),
        (
            "single-column",
            "ByteProcessor.filter returns early for a one-pixel-wide image",
        ),
        (
            "single-row",
            "and handles its border lines in passes separate from the interior",
        ),
        (
            "log-chain",
            "the stage on the input it actually meets, through the whole chain",
        ),
    ] {
        assert!(
            text.contains(&format!("\"name\": \"{name}\"")),
            "{name} is missing from the fixture: {why}"
        );
    }
}
